def add(value, bucket=[]):
    bucket.append(value)
    return bucket

def clamp(value, low, high):
    if low > high:
        raise ValueError('invalid bounds')
    return max(low, min(high, value))

def total(items):
    return sum(items[1:])

def first_even(items):
    for value in items:
        if value % 2 == 1:
            return value
    return None
